files.Exploding/Frozen/CounterexampleArrival.l:
-- FROZEN-STATEMENT-BEGIN
noncomputable def Exploding.counterexampleArrival {d : ℕ}
    (η : Site d → ℤ) (hη : Explosive η) (x : Site d) : ℕ∞ :=
  sInf {t : ℕ∞ | ∃ n : ℕ, t = (n : ℕ∞) ∧ 1 ≤ n ∧
    0 < podo (counterexamplePile η hη) n x}
-- FROZEN-STATEMENT-END

files.Exploding/Frozen/CounterexampleSupport.l:
-- FROZEN-STATEMENT-BEGIN
noncomputable def Exploding.counterexampleSupport {d : ℕ}
    (η : Site d → ℤ) (hη : Explosive η) (t : ℕ) : Set (Fin d → ℝ) :=
  {y | 0 < podo (counterexamplePile η hη) t
    (nearestSite ((t : ℝ) • y))}
-- FROZEN-STATEMENT-END

files.Exploding/Frozen/CounterexampleThreshold:
-- FROZEN-STATEMENT-BEGIN
noncomputable def Exploding.counterexampleThreshold {d : ℕ}
    (η : Site d → ℤ) (_hη : Explosive η) : ℕ :=
  sInf {n : ℕ | 1 ≤ n ∧
    ¬ Stabilizable (fun x => η x + n * dirac (0 : Site d) x)}
-- FROZEN-STATEMENT-END

