\subsection{Proof of Theorem \ref{theorem:counterexample} for \texorpdfstring{$d \geq 3$}{d > 2}} \label{sec:proof_of_generalization}
Let $\eta^{(2D)}: \Z^2 \to \{1, 2, 3\}$ be the (possibly random) background defined in Section \ref{sec:counterexample_2D} and let $d \geq 3$ be given. Our higher-dimensional counterexample $\eta: \Z^d \to \{ 2 d - 3, 2 d -2, 2 d - 1\}$
is built by stacking the two-dimensional one, 
\begin{equation} \label{eq:stacked_tiling1}
\eta(x_1, x_2, \ldots, x_d) = 2  (d- 2) + \eta^{(2D)}(x_1, x_2) \mbox{ for all $x \in \Z^d$}.
\end{equation}
\subsubsection*{Step 1: Proof of \eqref{eq:counterexample_lower}}
The argument is identical to $d = 2$. 



\subsubsection*{Step 2: $\eta$ is explosive}

Let ${\eta'}^{(2D)}$ be the tiling of $\zeta_1', \zeta_2'$, defined in \eqref{eq:modified_checkerboard}.
The higher-dimensional analogue, $\eta': \Z^d \to \{ 2 d - 3, 2 d -2, 2 d - 1\}$ is also stacked, 
\begin{equation} \label{eq:stacked_tiling2}
\eta'(x_1, x_2, \ldots, x_d) := {\eta'}^{(2D)}(x_1, x_2) + 2  (d - 2).
\end{equation}
The argument is as before: we construct a toppling procedure that transforms $\eta$ into $\eta'$. Since $3  \delta_0 + \eta' \geq (2 d - 2)$ is box-crossing, it is not stabilizable. 

Topple the origin, all sites with $(2d - 1)$ chips, then all sites with $(2d - 2)$, then the column of $(2 d-3)$ near the origin. Let $\tilde{u}$ denote the odometer for this and $\tilde{u}^{(2D)}$ the two-dimensional version and observe that $\tilde{u}(x_1, x_2, \ldots, x_d) = \tilde{u}^{(2D)}(x_1,x_2)$. This implies,
\begin{align*}
&\sum_{i=1}^{d} (\tilde{u}(x-e_i) + \tilde{u}(x+e_i) - 2 \tilde{u}(x)) + \eta \\
&= \sum_{i=1}^2 (\tilde{u}^{(2D)}(x-e_i) + \tilde{u}^{(2D)}(x+e_i) - 2 \tilde{u}^{(2D)}(x)) + \eta \\
&= \sum_{i=1}^2 (\tilde{u}^{(2D)}(x-e_i) + \tilde{u}^{(2D)}(x+e_i) - 2 \tilde{u}^{(2D)}(x)) + \eta^{(2D)} + 2  (d-2) \\
&= {\eta'}^{(2D)} + 2  (d-2) \\
&= \eta'. 
\end{align*}
We conclude by observing $\eta'$ is box-crossing as $3  \delta_0 + \eta' \geq (2 d - 2)$ and every layer in the box  $\mathbf{B}^{(d)} := \{ x \in \Z^d : 0 \leq x \leq 3 \}$, contains at least one site with $(2 d - 1)$ chips. Indeed, for all $(3, 3, \mathbf{x}_{d-2}) \in \mathbf{B}^{(d)}$, 
\[
\eta'(3,3, \mathbf{x}_{d-2}) = {\eta'}^{(2D)}(3, 3) + 2  (d - 2) = (2 d - 1),
\]
and every layer in ${\eta'}^{(2D)}$ has at least one site with 3 chips. 




\subsubsection*{Step 3: Proof of \eqref{eq:counterexample_upper}}
Let $v_t^{(2D)}$ be the parallel toppling odometer for $\eta^{(2D)}$. By \eqref{eq:second_limit_upper_bound}
it suffices to show that
\begin{equation} \label{eq:parabolic_least_action}
v_t(x_1, x_2, \ldots, x_d) \leq v_t^{(2D)}(x_1,x_2). 
\end{equation}
This is a consequence of the parabolic least action principle (Lemma 2.3 in \cite{bou2020dynamic}) but 
we provide a self-contained proof here:

Suppose \eqref{eq:parabolic_least_action} holds at time $t$ and we want to show it holds at $(t+1)$.
Let $x$ be given. If $v_t(x) < v_t^{(2D)}(x_1,x_2)$ we are done. Hence, we may suppose $v_t(x) = v_t^{(2D)}(x_1,x_2)$
and 
\[
\Delta v_t(x) + \eta = \sum_{i=1}^d (v_t(x + e_i) + v_t(x - e_i) - 2 v_t(x)) + \eta \geq 2 d.
\]
By \eqref{eq:parabolic_least_action} at time $t$, this implies 
\[
\sum_{i=1}^2 (v_t^{(2D)}((x_1,x_2) + e_i) + v_t^{(2D)}((x_1,x_2) - e_i) - 2 v_t^{(2D)}(x_1,x_2)) + \eta \geq 2 d,
\]
and by \eqref{eq:stacked_tiling1}, 
\[
\Delta v_t^{(2D)}(x_1,x_2) + \eta^{(2D)}(x_1,x_2) \geq 2 d - 2  (d - 2) = 4,
\]
completing the proof.

To verify failure of convergence in the volume sense of Theorem
\ref{theorem:limit_shape}, choose the periodic two-dimensional background
obtained by using $\zeta_1$ in every tile, and for $d\geq3$ extend it by
\eqref{eq:stacked_tiling1}. For integer $t\geq1$, write
$A_t=\{y\in\R^d:\bar v_t(y)>0\}$ and $a_n=3+8n$.
For every $n\geq1$, $k\in\Z$, and $z\in\Z^{d-2}$, the cylinder
comparison, followed by \eqref{eq:parabolic_least_action} when $d\geq3$,
gives
\[
v_t(a_n,4k,z)=0\qquad(t<12n).
\]
When $d=2$, $z$ is the empty tuple in $\Z^0$, $\|z\|_1=0$, and trailing
empty coordinates below are omitted.
The site $e_2$ has fired by time $2$. The nearest-neighbor path from $e_2$
through $(1,1,0)$, $(1,4k+1,0)$, and $(1,4k+1,z)$ to
$(a_n,4k+1,z)$ has $a_n+|4k|+\|z\|_1$ edges. Every site after $e_2$
on this path has background height $2d-1$, so
\[
v_{a_n+|4k|+\|z\|_1+2}(a_n,4k+1,z)>0.
\]
Fix $\varepsilon_d=1/(100d)$ and
$\Omega_d=\{y\in\R^d:3/4<y_1<4/5,
\ |y_i|<\varepsilon_d\ (2\leq i\leq d)\}$.
For all sufficiently large integer $t$, a fixed positive proportion of the
nearest-site cells in an interior box of $\Omega_d$ have centers
$(a_n,4k,z)$ and satisfy $t<12n$ and
$a_n+|4k|+\|z\|_1+2\leq t$. The congruence conditions on the first two
coordinates have density $1/32$, and there is no restriction on the
remaining coordinates. Each such cell is absent from $A_t$, while its
translate by $e_2/t$ is present. Hence, for some $c_d>0$,
\[
\left|(A_t\triangle(A_t-e_2/t))\cap\Omega_d\right|\geq c_d
\qquad\text{for all sufficiently large integers }t.
\]
If $|A_t\triangle B|\to0$ for a measurable set $B$, then the triangle
inequality and local $L^1$ continuity of translation give
$|(A_t\triangle(A_t-e_2/t))\cap\Omega_d|\to0$, a contradiction.

\section{A criterion for exploding} \label{sec:criteria}

For Proposition \ref{prop:explosion_criteria}, let
$(\Omega,\mathcal F,\mathbf P)$ be the bounded-background probability
space of Section \ref{sec:generalization}. The criterion below will be
applied to a bounded reduction of the original product law.
For a finite domain $V \subset \Z^d$, we say  $\eta: V \to \Z$ is {\it recurrent} if the firing of $\partial V$ causes every site in $V$ to eventually topple. 
Specifically, the $V^c$-frozen parallel toppling odometer for initial conditions $w_0 = 1\{ x \in \partial V\}$, $s_0' = \eta + \Delta w_0$, 
is eventually 1 on $V$: $w_t |_{V} = 1$ for $t \geq |V|$. We say $\eta: \Z^d \to \Z$ is recurrent if its
restriction to $V$ is recurrent for every finite $V \subset \Z^d$.  The measure $\mathbf{P}$ is recurrent if $\mathbf{P}(\mbox{$\eta$ is recurrent}) = 1$. The following criterion follows from recurrence, finite-range dependence, and ordinary box-crossing. 

\begin{prop} \label{prop:explosion_criteria}
	If Hypotheses \ref{hyp:finite_range_of_dependence} and \ref{hyp:box_crossing} 
	are satisfied and $\mathbf{P}$ is recurrent
	then $\mathbf{P}$ is explosive. 
\end{prop}

\begin{proof}
The backgrounds of Section \ref{sec:generalization} satisfy $\eta\leq 2d-1$.
Recurrence of the singleton $\{x\}$ implies $\eta(x)\geq0$: after all
$2d$ external neighbors fire once, its height is $\eta(x)+2d$.
Thus $0\leq\eta\leq2d-1$ almost surely.

First suppose $d\geq2$. Given $\delta>0$, choose the tiling
$\{\mathcal B_k^{(j)}:j\in\Z^d\}$ from Hypothesis
\ref{hyp:box_crossing}, and let $X_j$ indicate that the $j$th box can
be crossed from each external face. Hypothesis
\ref{hyp:finite_range_of_dependence} makes $\{X_j\}$ finitely
dependent, with a dependence range bounded in terms of $K$ independently
of $k$. The domination theorem of \cite{liggett1997domination}, used
also in Section \ref{sec:generalization}, therefore gives, for $\delta$
small enough, a coupling in which $\{X_j\}$ dominates supercritical
independent site percolation. Almost surely there is an infinite
nearest-neighbor cluster $\mathcal C_\infty$ of boxes with $X_j=1$.

Fix one box $\mathcal B_k^{(j_0)}\in\mathcal C_\infty$ and set
$R=\max\{\|x\|_1:x\in\mathcal B_k^{(j_0)}\}$ and $N=(2d)^R$.
For the $N$-wave from the origin in \eqref{eq:n_wave}, induction on
$r=\|x\|_1$ gives
\[
u_t^{(N,0)}(x)\geq(2d)^{R-r}\qquad(r\leq R,\ t\geq r),
\]
because $\eta\geq0$. Hence every site of the chosen box topples.
If every site of one box in $\mathcal C_\infty$ has toppled, then all
sites of the shared external face of any adjacent box have toppled.
Comparison with that box's $\mathcal B_k^c$-frozen process, started by
one prescribed firing on this face, shows that every site of the
adjacent good box subsequently topples. Following finite paths in
$\mathcal C_\infty$ gives the $N$-wave infinite support, so it cannot
stabilize.

If $\eta+2dN\delta_0$ stabilized with terminal odometer $v_\infty$,
its stable origin height would imply $v_\infty(0)\geq N$. At every
$x\ne0$, stability and $0\leq s_\infty(x)<2d$ give
\[
\left\lfloor\frac{\eta(x)+\sum_{y\sim x}v_\infty(y)}{2d}\right\rfloor
=v_\infty(x).
\]
Induction in \eqref{eq:n_wave} would then give
$u_t^{(N,0)}\leq v_\infty$ for every $t$. Since $v_\infty$ has finite
support and finite values, the nondecreasing integer-valued $N$-wave
would stabilize, a contradiction. Thus $\eta$ is explosive.

For $d=1$, recurrence of an interval with zero height at both endpoints
is impossible: firing its two external neighbors starts no toppling.
Hence a recurrent stable background has at most one zero. Stationarity
under the finite-index sublattice makes the probability of a zero at
each site vanish, so $\eta\equiv1$ almost surely. Its $1$-wave from the
origin reaches both sites at distance $t$ by time $t$; the comparison
above proves explosion in this case as well.
\end{proof}

For the proof of Theorem \ref{theorem:explosive}, now use Proposition \ref{prop:explosion_criteria} as follows.
Let $\eta$ have the original common product law $\mathbf P=\bigotimes_{x\in\Z^d}\nu$ from that theorem, with $d\geq2$, $\nu(\{m\in\Z:m\geq d\})=1$, and $p:=\nu(\{2d-1\})\in(0,1]$.
Define $r_d:\Z\to\Z$ by $r_d(m)=2d-1$ if $m=2d-1$ and $r_d(m)=d$ otherwise, and set $\alpha_d(x):=r_d(\eta(x))$.
Almost surely $d\leq\alpha_d\leq2d-1$ and $\alpha_d\leq\eta$; the reduced law is $\mathbf P_d:=\bigotimes_{x\in\Z^d}((1-p)\delta_d+p\delta_{2d-1})$.
We prove exact recurrence and box-crossing for $\mathbf P_d$. Proposition \ref{prop:explosion_criteria} then gives explosion for $\alpha_d$, and monotonicity transfers box-crossing and explosion to the original $\eta$. Exact recurrence is asserted only for the reduced stable field. The dimension-one box-crossing case is separate.



\subsection{Dimensional reduction}
Let $Q_n^{(d)} := \{ x \in \Z^d : 1 \leq x \leq n\}$ and denote each of the (internal) $2d$ faces of $Q_n^{(d)}$ as 
\begin{equation}\label{eq:faces_definition}
\begin{aligned}
\mathcal{F}_i(Q_n^{(d)}) &:= \{ x \in Q_n^{(d)} : x_i = 1\} \\
\mathcal{F}_{d+i}(Q_n^{(d)}) &:= \{ x \in Q_n^{(d)} : x_i = n\}.
\end{aligned}
\end{equation}
We show that after firing the outer boundary of $\mathcal{F}_i(Q_n^{(d)})$, 
the sandpile dynamics on $\mathcal{F}_i(Q_n^{(d)})$ can be coupled
with $(d-1)$-dimensional sandpile dynamics on $Q_n^{(d-1)}$.

Specifically, fix $i=1$ and write points of
$\mathcal F_1(Q_n^{(d)})$ as $(1,\mathbf x_{d-1})$. Let
$\eta^{(d)}:Q_n^{(d)}\to\Z$ be given. In the constrained
$Q_n^{(d)}$- and $Q_n^{(d-1)}$-frozen processes, prescribe
\begin{equation}\label{eq:constrained_toppling}
\begin{aligned}
&u_0^{(d)}(0,\mathbf y)=1
  &&(\mathbf y\in Q_n^{(d-1)}),\\
&u_0^{(d-1)}(\mathbf y)=u_0^{(d)}(1,\mathbf y)\in\{0,1\}
  &&(\mathbf y\in\partial Q_n^{(d-1)}),\\
&u_0^{(d-1)}(\mathbf x)=u_0^{(d)}(1,\mathbf x)=0
  &&(\mathbf x\in Q_n^{(d-1)}),\\
&s_0^{(d)}(1,\mathbf x)=\eta^{(d)}(1,\mathbf x)
  +\Delta u_0^{(d)}(1,\mathbf x)
  &&(\mathbf x\in Q_n^{(d-1)}),\\
&\eta^{(d-1)}(\mathbf x)=\eta^{(d)}(1,\mathbf x)-1,\qquad
 s_0^{(d-1)}(\mathbf x)=\eta^{(d-1)}(\mathbf x)
  +\Delta u_0^{(d-1)}(\mathbf x)
  &&(\mathbf x\in Q_n^{(d-1)}).
\end{aligned}
\end{equation}
All other external odometers are initially zero. The tangential
external values may be chosen either all zero, for box-crossing, or all
one, for recurrence.
and constraints,
\begin{equation} \label{eq:frozen_constraint}
\begin{aligned}
u_t^{(d)}(x_1,\mathbf{x}_{d-1}) &= 0 \quad \mbox{ for all $x_1 > 1$} \\
u_t^{(d)}(1, \mathbf{x}_{d-1}) & \leq 1 \\
u_t^{(d-1)}(\mathbf{x}_{d-1}) &\leq 1,
\end{aligned}
\end{equation}
for all $t \geq 0$. Specifically, we take initial conditions given by \eqref{eq:constrained_toppling}
and enforce the constraints \eqref{eq:frozen_constraint} by defining the odometer sequences for $t \geq 0$ as
\[
u_{t+1}^{(d)}(x) = 
\begin{cases}
u_t^{(d)}(x) \qquad \mbox{if $x \in (Q_n^{(d)})^c$} \\
u_t^{(d)}(x) \qquad \mbox{if $x_1 > 1$} \\
u_t^{(d)}(x) \qquad \mbox{if $x_1 = 1$ and $u_t^{(d)}(x)  = 1$} \\
u_t^{(d)}(x) + 1\{s_t^{(d)}(x) \geq 2 d\} \qquad \mbox{otherwise}
\end{cases}
\]
and
\[
u_{t+1}^{(d-1)}(\mathbf x_{d-1}) = 
\begin{cases}
u_t^{(d-1)}(\mathbf x_{d-1}) \qquad
\mbox{if $\mathbf x_{d-1}\in(Q_n^{(d-1)})^c$} \\
u_t^{(d-1)}(\mathbf x_{d-1}) \qquad \mbox{if $u_t^{(d-1)}(\mathbf{x}_{d-1}) = 1$} \\
u_t^{(d-1)}(\mathbf x_{d-1}) + 1\{s_t^{(d-1)}(\mathbf x_{d-1}) \geq 2 (d-1)\} \qquad \mbox{otherwise}.
\end{cases}
\]
The sandpile sequences are defined as in the unconstrained case. 
Observe that constrained frozen toppling odometers are dominated by the corresponding unconstrained odometers.

We prove the following by an induction on time. Note that a symmetric result holds for every face. 
\begin{prop} \label{prop:dimensional_reduction}
	For all $t \geq 0$ and $(1, \mathbf{x}_{d-1}) \in \mathcal{F}_1(Q_n^{(d)})$, 
	\begin{equation} \label{eq:odometer_reduction}
	u_t^{(d)}(1,\mathbf{x}_{d-1}) = u_t^{(d-1)}(\mathbf{x}_{d-1})
	\end{equation}
	and
	\begin{equation} \label{eq:sandpile_reduction}
	s_t^{(d)}(1,\mathbf{x}_{d-1}) = s_t^{(d-1)}(\mathbf{x}_{d-1}) + 2 \qquad \mbox{ if $ u_t^{(d)}(1,\mathbf{x}_{d-1}) = 0 $}.
	\end{equation}
\end{prop}

\begin{proof}
	For all $t \geq 0$, if  $u_{t}^{(d)}(1,\mathbf{x}_{d-1}) = 0$ and $u_t^{(d)}(1,\mathbf{y}_{d-1}) = u_t^{(d-1)}(\mathbf{y}_{d-1})$ for all $\mathbf{y}_{d-1}$, 
	\begin{align*}
	&s_{t}^{(d)}(1, \mathbf{x}_{d-1}) \\
	&=  \eta^{(d)}(1, \mathbf{x}_{d-1})  \\
	&+ \left( -2 u_{t}^{(d)}(1, \mathbf{x}_{d-1}) + u_{t}^{(d)}(0, \mathbf{x}_{d-1}) + u_{t}^{(d)}(2, \mathbf{x}_{d-1}) \right) \\
	&+ \sum_{i=2}^d \left( u_{t}^{(d)}((1,\mathbf{x}_{d-1}) + e_i) + u_{t}^{(d)}((1,\mathbf{x}_{d-1})-e_i) - 2 u_{t}^{(d)}(1,\mathbf{x}_{d-1}) \right) \\
	&= \eta^{(d-1)}(\mathbf{x}_{d-1}) + 2 \\
	&+  \sum_{i=1}^{d-1} \left( u_{t}^{(d-1)}(\mathbf{x}_{d-1} + e_i) + u_{t}^{(d-1)}(\mathbf{x}_{d-1}-e_i) - 2 u_{t}^{(d-1)}(\mathbf{x}_{d-1}) \right) \\
	&=s_{t}^{(d-1)}(\mathbf{x}_{d-1})+2.
	\end{align*}

The initial conditions give \eqref{eq:odometer_reduction} at $t=0$;
the calculation above gives \eqref{eq:sandpile_reduction} whenever the
common face odometer is zero. Suppose both assertions hold at time $t$.
At a face site where the common odometer is already one, both
constrained odometers remain one. Where it is zero,
\eqref{eq:sandpile_reduction} gives
\[
s_t^{(d)}(1,\mathbf x_{d-1})\geq2d
\quad\Longleftrightarrow\quad
s_t^{(d-1)}(\mathbf x_{d-1})\geq2(d-1).
\]
Thus both odometers make the same update, proving
\eqref{eq:odometer_reduction} at time $t+1$; the calculation above then
proves \eqref{eq:sandpile_reduction} wherever the new common odometer
is zero.

\end{proof}







\subsection{\texorpdfstring{$\mathbf{P}_d$}{P_d} is recurrent}
Since $d\leq\alpha_d\leq2d-1$, monotonicity of exact recurrence within this stable range reduces the claim for $\mathbf P_d$ to the following deterministic proposition.
\begin{prop} \label{prop:recurrence}
	For every $d \geq 1$, $\eta:\Z^d \to \{d\}$ is recurrent.
\end{prop}
\begin{proof}
For a background bounded by $2d-1$, a process with each external
neighbor fired once has odometer at most one in its domain: the
constant-one odometer is a supersolution of the toppling update.
Consequently it suffices to prove recurrence for translated cubes.
Indeed, put any finite $V$ together with $\partial V$ inside such a
cube. Once that cube topples throughout, each site of $\partial V$
has toppled once; comparison with the $V^c$-frozen process, which has
all of $\partial V$ fired at time zero, makes every site of $V$
topple. We induct first on dimension and then on cube side length. In dimension one, firing both external
neighbors of a constant-one interval makes its sites topple successively.
For every dimension, $n=1$ is immediate because the unique site receives
one chip from each of its $2d$ external neighbors. For $n=2$, every
site receives one chip from each of its $d$ external neighbors, bringing
its height from $d$ to $2d$.

Now let $n\geq3$ and assume recurrence for side length $n-2$ in
dimension $d$ and for all side lengths in dimension $d-1$. The correct
decomposition is
\begin{equation}\label{eq:cube_decomp}
Q_n^{(d)}=\bigl(\mathbf 1+Q_{n-2}^{(d)}\bigr)
 \cup\bigcup_{i=1}^{2d}\mathcal F_i(Q_n^{(d)}),
\qquad \mathbf 1=(1,\ldots,1).
\end{equation}
Fire the external boundary of $Q_n^{(d)}$. For each face, compare the
resulting process with the constrained process of Proposition
\ref{prop:dimensional_reduction}: fire its outer normal external face
and its tangential external neighbors, and freeze all other sites off
the selected face. Under \eqref{eq:constrained_toppling}, the reduced
$(d-1)$-dimensional background is the constant $d-1$ with all its
external neighbors fired once. The dimension induction and
\eqref{eq:odometer_reduction} therefore make every site of the selected
face topple. The full boundary-firing process dominates each such
constrained process, so every outer face topples. Every external
neighbor of $\mathbf 1+Q_{n-2}^{(d)}$ lies on an outer face. Comparing
with its boundary-firing process and using the side-length induction
makes the inner cube topple as well. Equation \eqref{eq:cube_decomp}
then covers every site of $Q_n^{(d)}$.
\end{proof}
\begin{remark}
	The argument given here is similar to the proof of Lemma 3.1 in \cite{schonmann1992behavior}.
\end{remark}

\subsection{\texorpdfstring{$\mathbf{P}$}{P} is box-crossing}
A coupling between the sandpile and bootstrap percolation has been observed before  \cite{fey2010growth}. 
Bootstrap percolation is a cellular automata on $\Z^d$ with a random initial state and a deterministic update rule. 
Every site $x \in \Z^d$ starts off as {\it infected} independently at random with probability $p$. 
Infected sites remain infected and if an uninfected site contains at least $d$ neighbors which
are infected, it becomes infected.

These dynamics exactly match parallel toppling for a background $\eta':\Z^d \to \{d, 2 d\}$
where sites are constrained to topple at most once.
Infected sites are those which have toppled, and sites with $2 d$ chips start as infected. Indeed, any 
site beginning with $d$ chips topples if and only if it has at least $d$ neighbors which have toppled.


We first prove box-crossing for the reduced law $\mathbf P_d$ using this coupling and Schonmann's large-deviation result, then transfer it to the original law $\mathbf P$ by monotonicity. Borrowing the terminology of Schonmann, we say a cube $Q_n^{(d)} \subset \Z^d$ is $\eta'-${\it internally spanned}
if the $(Q_n^{(d)})^c$-frozen parallel toppling procedure with $u_0 = 0$, $s_0' = \eta'$, and sites constrained to topple at most once, concludes with every site in $Q_n^{(d)}$ toppling. 




\begin{prop}[\cite{schonmann1992behavior}] \label{prop:schonnmann_bootstrap}
	Let
	\[
	\eta'(x) := \begin{cases} 2 d &\mbox{with probability $p$} \\
	d &\mbox{otherwise.}
	\end{cases}
	\]
	There are constants $c,C$ depending only on dimension and $p > 0$
	so that 
	\begin{equation}
	P(\mbox{$Q_n^{(d)}$ is $\eta'$-internally spanned}) \geq 1 -  c \exp(-C n).
	\end{equation}
\end{prop}


We use Proposition \ref{prop:schonnmann_bootstrap} to show $\mathbf{P}$ is box-crossing. 

\begin{prop}
    For $d\geq2$, the original product law $\mathbf P$ is box-crossing. In dimension one, any law supported on backgrounds $\eta\geq1$ is box-crossing.
\end{prop}
\begin{proof}
	The claim is immediate in dimension one: a singleton box is crossed from either external face after its prescribed seed delivers one chip, since the height is at least one.
	Let $D=d+1\geq2$ be the original dimension. In this dimension write $\nu$ for the common original marginal, with $\nu(\{m:m\geq D\})=1$, put $p=\nu(\{2D-1\})\in(0,1]$, let $\eta^{(D)}$ have that product law, and set $\alpha_D=r_D\circ\eta^{(D)}$. Then $\alpha_D\leq\eta^{(D)}$ almost surely and $\alpha_D$ has common marginal $(1-p)\delta_D+p\delta_{2D-1}$. For $n\geq1$, decompose the box into layers
	\[
	Q_n^{(D)} = \bigcup_{i=1}^{n} \mathcal{L}_i,
	\]
	where $\mathcal{L}_i := \{ x \in Q_n^{(D)} : x = (i, \mathbf{x}_d)\}$.
	The projection of each layer to a $d$-dimensional box is $\mathcal{L}_i^{(d)}$. Let 
	\begin{align*}
	\Omega_i' &:= \{\eta^{(D)} : \mbox{$\mathcal{L}_i^{(d)}$ is $\eta'_i$-internally spanned, where $\eta'_i(\mathbf{x}_d) := \alpha_D(i,\mathbf{x}_d) - 1$} \}
	\end{align*}
	The variables $\eta'_i(\mathbf{x}_d)$, over all layers and sites, are independent with common marginal $(1-p)\delta_d+p\delta_{2d}$.
	Let 
	\[
	\Omega'  := \bigcap_{i=1}^n \Omega_i'. 
	\]
On $\Omega'$, start with one prescribed firing on the external face
normal to $e_1$. The internal spanning of $\mathcal L_1^{(d)}$ and
Proposition \ref{prop:dimensional_reduction}, with zero tangential
external odometers, make every site of $\mathcal L_1$ topple. Its
firings deliver the prescribed external face to $\mathcal L_2$; the
same comparison applies successively to all $n$ layers. Hence
$Q_n^{(D)}(\alpha_D)$ is crossed in direction $e_1$, and monotonicity
transfers this crossing to $Q_n^{(D)}(\eta^{(D)})$.
Proposition \ref{prop:schonnmann_bootstrap} and a union bound give
$\mathbf P(\Omega'^c)\leq n c\exp(-Cn)$; symmetry gives every
direction.

\end{proof}

